/* Khaana - "Cook with what you have"
   Loads the curated recipe database, scores each recipe against the cook's
   pantry and constraints, and renders ranked suggestions.
   Everything here is client-side; the data files are the source of truth. */
(function () {
  'use strict';

  var PANTRY_URL = 'data/pantry.json';
  // The light index, not the full database: the Cook page only needs
  // ingredient ids and tags to rank. Generated by tools/split-recipes.py.
  var RECIPES_URL = 'data/recipes-index.json';
  var STORAGE_KEY = 'khaana.pantry.v1';
  // Below this share of a recipe's ingredients the suggestion stops being
  // useful — it is a shopping list with a photo attached.
  var MIN_PCT = 20;
  // Nothing is ticked on a first visit.
  //
  // A four-item starter pantry was tried and removed. It made the page look
  // busy before the reader had done anything, and worse, it scored every
  // search result against ingredients they had never chosen: searching
  // "biryani" returned dishes labelled 13% with a long Missing list, which
  // reads as though the search had been filtered by the pantry. An empty
  // pantry means the two routes stay visibly independent.
  var DEFAULT_PANTRY = [];
  // The size of the database is not something the page advertises. Any count
  // above this is reported as "100+" rather than exactly.
  var COUNT_CAP = 100;
  function shown(n) { return n > COUNT_CAP ? COUNT_CAP + '+' : String(n); }

  var pantry = null;
  var recipes = [];
  var selected = new Set();

  var el = function (id) { return document.getElementById(id); };

  /* ---------- scoring ---------- */

  // A recipe ingredient is one of: have | substitute | missing.
  // Staples (salt, oil, water, sugar) are assumed present in every kitchen.
  function classify(ingId, has, staples, subs) {
    if (staples.indexOf(ingId) !== -1) return { state: 'have', staple: true };
    if (has.has(ingId)) return { state: 'have' };
    var options = subs[ingId] || [];
    for (var i = 0; i < options.length; i++) {
      if (has.has(options[i].id)) {
        return { state: 'substitute', via: options[i] };
      }
    }
    return { state: 'missing' };
  }

  function scoreRecipe(recipe, has, filters) {
    var staples = pantry.staples;
    var subs = pantry.substitutions;

    var lines = recipe.ingredients.map(function (ing) {
      var c = classify(ing.id, has, staples, subs);
      return {
        id: ing.id,
        name: nameFor(ing.id),
        qty: ing.qty,
        note: ing.note,
        essential: ing.essential !== false,
        state: c.state,
        staple: !!c.staple,
        via: c.via || null
      };
    });

    // Only non-staple lines count toward the match figure, otherwise every
    // recipe would score a free 15% for having salt.
    var counted = lines.filter(function (l) { return !l.staple; });
    var essentials = counted.filter(function (l) { return l.essential; });

    var earned = 0, possible = 0;
    counted.forEach(function (l) {
      // Essentials are weighted 1.0, optional extras 0.35: not having a
      // garnish should barely dent the score, missing the main pulse should.
      var w = l.essential ? 1 : 0.35;
      possible += w;
      if (l.state === 'have') earned += w;
      else if (l.state === 'substitute') earned += w * (1 - (l.via.penalty || 0.2));
    });

    var pct = possible > 0 ? Math.round((earned / possible) * 100) : 0;

    var missingEssential = essentials.filter(function (l) { return l.state === 'missing'; });
    var subbedEssential = essentials.filter(function (l) { return l.state === 'substitute'; });
    var missingAny = counted.filter(function (l) { return l.state === 'missing'; });

    return {
      recipe: recipe,
      lines: lines,
      pct: pct,
      missingEssential: missingEssential,
      subbedEssential: subbedEssential,
      missingAll: missingAny,
      excluded: excludedBy(recipe, filters)
    };
  }

  // Hard constraints. These remove a recipe rather than lowering its score,
  // because "vegan" and "I have 20 minutes" are not preferences you rank by.
  function excludedBy(recipe, f) {
    var reasons = [];
    var total = recipe.prepMinutes + recipe.cookMinutes;

    f.diets.forEach(function (d) {
      if (recipe.tags.indexOf(d) === -1) reasons.push(labelForTag(d));
    });
    if (f.maxTime && total > f.maxTime) reasons.push('over ' + f.maxTime + ' min');

    var missingKit = (recipe.equipment || []).filter(function (e) {
      return f.equipment.length > 0 && f.equipment.indexOf(e) === -1;
    });
    if (missingKit.length) reasons.push('needs ' + missingKit.map(labelForEquip).join(', '));

    return reasons;
  }

  /* ---------- lookups ---------- */

  var NAME_CACHE = {};
  function nameFor(id) {
    if (NAME_CACHE[id]) return NAME_CACHE[id];
    var found = id;
    pantry.categories.forEach(function (c) {
      c.items.forEach(function (i) { if (i.id === id) found = i.name; });
    });
    if (found === id) {
      // staples and anything not in the selectable catalogue
      found = id.replace(/-/g, ' ').replace(/\b\w/g, function (m) { return m.toUpperCase(); });
    }
    NAME_CACHE[id] = found;
    return found;
  }

  var TAG_LABELS = {
    vegetarian: 'vegetarian', vegan: 'vegan', 'gluten-free': 'gluten-free',
    'dairy-free': 'dairy-free', 'nut-free': 'nut-free',
    'no-onion-garlic': 'no onion/garlic', pescatarian: 'pescatarian'
  };
  function labelForTag(t) { return TAG_LABELS[t] || t; }

  var EQUIP_LABELS = {
    stovetop: 'a stovetop', 'pressure-cooker': 'a pressure cooker', steamer: 'a steamer',
    blender: 'a blender', oven: 'an oven or grill', kadhai: 'a deep pan for frying',
    tawa: 'a flat griddle'
  };
  function labelForEquip(e) { return EQUIP_LABELS[e] || e; }

  /* ---------- rendering ---------- */

  function renderPantry() {
    var wrap = el('pantry-groups');
    wrap.innerHTML = '';
    pantry.categories.forEach(function (cat) {
      var group = document.createElement('div');
      group.className = 'pantry-group';
      var h = document.createElement('h3');
      h.textContent = cat.label;
      group.appendChild(h);

      var list = document.createElement('div');
      list.className = 'pantry-items';
      cat.items.forEach(function (item) {
        var id = 'ing-' + item.id;
        var lab = document.createElement('label');
        lab.className = 'ing';
        lab.setAttribute('for', id);
        var cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.id = id;
        cb.value = item.id;
        cb.checked = selected.has(item.id);
        cb.addEventListener('change', function () {
          if (cb.checked) selected.add(item.id); else selected.delete(item.id);
          persist();
          update();
        });
        lab.appendChild(cb);
        lab.appendChild(document.createTextNode(item.name));
        list.appendChild(lab);
      });
      group.appendChild(list);
      wrap.appendChild(group);
    });
  }

  function readFilters() {
    var diets = Array.prototype.slice
      .call(document.querySelectorAll('input[name="diet"]:checked'))
      .map(function (i) { return i.value; });
    var equipment = Array.prototype.slice
      .call(document.querySelectorAll('input[name="equip"]:checked'))
      .map(function (i) { return i.value; });
    var t = el('f-time').value;
    return {
      diets: diets,
      equipment: equipment,
      maxTime: t ? parseInt(t, 10) : null
    };
  }

  // Text search over name, region and ingredient names. Matching is on the
  // recipe rather than the pantry, so it deliberately ignores the MIN_PCT floor
  // — someone looking up a dish by name wants to find it and see what it needs,
  // not be told they are short of it.
  function searchQuery() {
    var box = el('recipe-search');
    return box ? box.value.trim().toLowerCase() : '';
  }

  // Everything a cook might reasonably type: the dish, where it is from, what
  // it says it is, what goes in it, the diet tags, how hard it is and what it
  // needs to cook in. Tags are matched on their readable label as well as their
  // id, so "no onion" and "gluten free" both work.
  /* Three tiers, because where a word lands changes what it means: the dish
     name is what someone is usually typing, region and diet are how they
     narrow it, and the ingredient list is the long tail. */
  function doc(s) {
    if (s._doc) return s._doc;
    var r = s.recipe;
    var strong = [r.region, r.subtitle || '', r.difficulty || ''];
    (r.tags || []).forEach(function (t) { strong.push(t, labelForTag(t), t.replace(/-/g, ' ')); });
    (r.equipment || []).forEach(function (e) { strong.push(e, labelForEquip(e), e.replace(/-/g, ' ')); });
    (r.allergens || []).forEach(function (a) { strong.push(a); });
    var body = [];
    s.lines.forEach(function (l) { body.push(l.name, l.id.replace(/-/g, ' ')); });
    s._doc = window.KhaanaMatch.prepare({
      title: r.name, strong: strong.join(' '), body: body.join(' ')
    });
    return s._doc;
  }

  // Tokenising is the same work for every recipe in a pass, so it is done once
  // per distinct query rather than 536 times.
  var qParts = { q: null };
  function queryParts(q) {
    if (qParts.q !== q) {
      qParts = { q: q, toks: window.KhaanaMatch.tokens(q), phrase: window.KhaanaMatch.norm(q) };
    }
    return qParts;
  }

  function queryScore(s, q) {
    if (!q) return 0;
    var p = queryParts(q);
    if (!p.toks.length) return 0;
    return window.KhaanaMatch.score(doc(s), p.toks, p.phrase);
  }

  function matchesQuery(s, q) {
    if (!q) return true;
    var p = queryParts(q);
    if (!p.toks.length) return true;
    return queryScore(s, q) > 0;
  }

  function update() {
    var filters = readFilters();
    var has = selected;
    var q = searchQuery();

    el('pantry-count').textContent = selected.size;

    var scored = recipes.map(function (r) { return scoreRecipe(r, has, filters); });

    var eligible = scored.filter(function (s) { return s.excluded.length === 0; });
    var blocked = scored.filter(function (s) { return s.excluded.length > 0; });

    // A dish you have under a fifth of is a shopping list, not a suggestion.
    // Only applied once the cook has ticked something — before that every score
    // is 0 and this would empty the page.
    var sparse = [];
    if (selected.size > 0 && !q) {
      sparse = eligible.filter(function (s) { return s.pct < MIN_PCT; });
      eligible = eligible.filter(function (s) { return s.pct >= MIN_PCT; });
    }

    if (q) {
      eligible = eligible.filter(function (s) { return matchesQuery(s, q); });
      blocked = blocked.filter(function (s) { return matchesQuery(s, q); });
    }

    // Someone who typed a dish name wants that dish, whatever their pantry
    // says. Scored once per recipe here rather than inside the comparator,
    // which would recompute it on every comparison.
    if (q) eligible.forEach(function (s) { s._qs = queryScore(s, q); });

    eligible.sort(function (a, b) {
      if (q && b._qs !== a._qs) return b._qs - a._qs;
      if (b.pct !== a.pct) return b.pct - a.pct;
      if (a.missingEssential.length !== b.missingEssential.length) {
        return a.missingEssential.length - b.missingEssential.length;
      }
      return (a.recipe.prepMinutes + a.recipe.cookMinutes) -
             (b.recipe.prepMinutes + b.recipe.cookMinutes);
    });

    renderResults(eligible, blocked, filters, sparse);
  }

  // A plain restatement of what the results are filtered by, so the reader can
  // see it without scrolling back up to the panel. Ingredients and filters take
  // separate labelled rows: run together in one comma list, a filter such as
  // "vegetarian" just reads as one more thing in the pantry.
  function renderSelectedLine(filters) {
    var line = el('selected-line');
    if (!line) return;

    // While searching, the pantry is not narrowing anything, so listing it
    // above the results would claim otherwise.
    var chosen = (selected.size && !searchQuery())
      ? Array.from(selected).map(nameFor).sort().join(', ')
      : '';

    var applied = [];
    if (filters.diets.length) applied.push(filters.diets.map(labelForTag).join(', '));
    if (filters.maxTime) applied.push('under ' + filters.maxTime + ' minutes');
    // EQUIP_LABELS carry an article because they are read in a sentence
    // ("needs a pressure cooker"). In a filter list the article is wrong.
    if (filters.equipment.length) {
      applied.push(filters.equipment
        .map(function (e) { return labelForEquip(e).replace(/^an? /, ''); })
        .join(', '));
    }

    if (!chosen && !applied.length) { line.hidden = true; line.innerHTML = ''; return; }

    function row(label, text, alt) {
      return '<span class="selected-row">' +
               '<span class="selected-label' + (alt ? ' alt' : '') + '">' + label + '</span> ' +
               esc(text) +
             '</span>';
    }

    var html = '';
    if (chosen) html += row('Selected', chosen, false);
    // · passes through esc() untouched, so no entity round-trip needed.
    if (applied.length) html += row('Filters', applied.join(' · '), true);

    line.hidden = false;
    line.innerHTML = html;
  }

  function renderResults(eligible, blocked, filters, sparse) {
    var out = el('results');
    out.innerHTML = '';
    renderSelectedLine(filters);

    var hidden = (sparse || []).length;
    var summary = el('results-summary');
    var q = searchQuery();
    var PAGE = 20;

    // "Showing 20 of 20" is noise, and so is a running total once the reader
    // has everything. Only mention the total while some of it is still hidden.
    function countPhrase(drawn, total) {
      var noun = ' recipe' + (total === 1 ? '' : 's');
      return drawn < total ? 'Showing ' + drawn + ' of ' + shown(total) + noun
                           : shown(total) + noun;
    }

    function setSummary(drawn) {
      var total = eligible.length;
      if (q) {
        summary.textContent = total === 0
          ? 'No recipe matches \u201c' + q + '\u201d within your filters.'
          : countPhrase(drawn, total) + ' matching \u201c' + q + '\u201d.';
      } else if (selected.size === 0) {
        summary.textContent = countPhrase(drawn, total) +
          '. Tick what is in your kitchen to rank them by your pantry.';
      } else {
        // Say what was withheld. A bare count would read as "that is everything".
        summary.textContent = countPhrase(drawn, total) +
          ' you can mostly make, ranked by how much of each you already have.' +
          (hidden ? ' ' + shown(hidden) + ' more need over ' + (100 - MIN_PCT) +
                    '% of their ingredients bought in, so they are not shown.' : '');
      }
    }

    if (eligible.length === 0) {
      var none = document.createElement('p');
      none.className = 'no-results';
      none.textContent = hidden
        ? 'Nothing reaches ' + MIN_PCT + '% of its ingredients from your pantry yet. ' +
          'Tick a few more staples, or loosen the time and equipment filters.'
        : 'Nothing fits those constraints yet. Try loosening the time limit or the equipment list.';
      out.appendChild(none);
    }

    // The list is ranked, so the tail is the part the cook can least make.
    // Twenty is about a screen and a half; revealing the rest a page at a time
    // keeps the DOM small. The summary is rewritten on each page so it never
    // goes stale against what is actually on screen.
    var drawn = 0;

    var more = document.createElement('button');
    more.type = 'button';
    more.className = 'show-more';

    function draw() {
      eligible.slice(drawn, drawn + PAGE).forEach(function (s) {
        out.insertBefore(card(s, !!q || selected.size === 0), more);
      });
      drawn = Math.min(drawn + PAGE, eligible.length);
      var left = eligible.length - drawn;
      if (left <= 0) {
        more.remove();
      } else {
        more.textContent = 'Show ' + Math.min(PAGE, left) + ' more (' + shown(left) + ' left)';
      }
      setSummary(drawn);
    }

    out.appendChild(more);
    more.addEventListener('click', draw);
    draw();

    var bwrap = el('blocked');
    bwrap.innerHTML = '';
    if (blocked.length) {
      var h = document.createElement('h3');
      h.className = 'blocked-head';
      h.textContent = 'Ruled out by your filters (' + shown(blocked.length) + ')';
      bwrap.appendChild(h);
      blocked.forEach(function (s) {
        var p = document.createElement('p');
        p.className = 'blocked-row';
        p.innerHTML = '<a href="recipes/' + s.recipe.id + '.html">' + esc(s.recipe.name) +
          '</a> <span>' + esc(s.excluded.join(' / ')) + '</span>';
        bwrap.appendChild(p);
      });
    }
  }

  /* `searching` strips the pantry read-out. Also passed when the pantry is
     empty: "0%" and "0/12 ingredients on hand" on every card is noise, and it
     reads as a verdict on the recipe rather than on an untouched pantry. Search and the pantry are two
     independent ways in, so a searched result should not be scored against a
     pantry the reader may not have been using: with the four-item starter
     pantry every hit otherwise showed "13%" and a long Missing list, which
     reads as though the search had been filtered by it. */
  function card(s, searching) {
    var r = s.recipe;
    var a = document.createElement('a');
    a.className = 'match-card';
    a.href = 'recipes/' + r.id + '.html';

    var have = s.lines.filter(function (l) { return !l.staple && l.state === 'have'; }).length;
    var countable = s.lines.filter(function (l) { return !l.staple; }).length;

    var missBits = s.missingAll.slice(0, 4).map(function (l) { return esc(l.name); }).join(', ');
    var extraMiss = s.missingAll.length > 4 ? ' +' + (s.missingAll.length - 4) + ' more' : '';

    var subLines = s.lines.filter(function (l) { return l.state === 'substitute'; });

    var thumb = r.image
      ? '<img src="' + esc(r.image.src) + '" alt="' + esc(r.image.alt) + '" loading="lazy" />'
      : '<span class="match-noimg" aria-hidden="true">' + esc(r.name.charAt(0)) + '</span>';

    a.innerHTML =
      '<div class="match-thumb">' + thumb +
        (searching ? '' :
          '<span class="match-pct" data-tier="' + tier(s.pct) + '">' + s.pct + '%</span>') +
      '</div>' +
      '<div class="match-body">' +
        '<div class="match-meta">' + esc(r.region) + ' &middot; ' + esc(r.difficulty) +
          ' &middot; ' + (r.prepMinutes + r.cookMinutes) + ' min &middot; serves ' + r.servings + '</div>' +
        '<h3>' + esc(r.name) + '</h3>' +
        '<p class="match-sub">' + esc(r.subtitle) + '</p>' +
        '<div class="diet-tags">' + r.tags.map(function (t) {
            return '<span class="diet-tag">' + esc(labelForTag(t)) + '</span>';
          }).join('') + '</div>' +
        (searching ? '' :
        '<div class="match-lines">' +
          '<div class="ml have"><strong>' + have + '/' + countable + '</strong> ingredients on hand</div>' +
          (subLines.length ? '<div class="ml sub"><strong>' + subLines.length +
             '</strong> can be substituted: ' + subLines.map(function (l) {
               return esc(l.name) + ' &rarr; ' + esc(nameFor(l.via.id));
             }).join('; ') + '</div>' : '') +
          (s.missingAll.length ? '<div class="ml miss"><strong>Missing:</strong> ' + missBits + extraMiss + '</div>'
                               : '<div class="ml none">Nothing missing</div>') +
        '</div>') +
      '</div>';
    return a;
  }

  function tier(p) { return p >= 90 ? 'high' : p >= 65 ? 'mid' : 'low'; }

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  /* ---------- persistence ---------- */

  function persist() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(selected))); }
    catch (e) { /* private mode; not worth surfacing */ }
  }
  function restore() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        // A saved pantry wins, including a deliberately emptied one — clearing
        // writes "[]", which is distinct from never having visited.
        JSON.parse(raw).forEach(function (id) { selected.add(id); });
        return;
      }
    } catch (e) { /* private mode; fall through to the default */ }
    DEFAULT_PANTRY.forEach(function (id) { selected.add(id); });
  }

  /* ---------- boot ---------- */

  function wire() {
    document.querySelectorAll('input[name="diet"], input[name="equip"]').forEach(function (i) {
      i.addEventListener('change', update);
    });
    el('f-time').addEventListener('change', update);
    el('clear-pantry').addEventListener('click', function () {
      selected.clear();
      persist();
      renderPantry();
      update();
    });
    var recipeSearch = el('recipe-search');
    if (recipeSearch) {
      recipeSearch.addEventListener('input', update);
      recipeSearch.addEventListener('search', update);   // the native clear button
    }
    var clearSearch = el('clear-search');
    if (clearSearch) {
      clearSearch.addEventListener('click', function () {
        recipeSearch.value = '';
        recipeSearch.focus();
        update();
      });
    }

    var search = el('pantry-search');
    search.addEventListener('input', function () {
      var q = search.value.trim().toLowerCase();
      document.querySelectorAll('.pantry-group').forEach(function (g) {
        var any = false;
        g.querySelectorAll('.ing').forEach(function (l) {
          var hit = !q || l.textContent.toLowerCase().indexOf(q) !== -1;
          l.style.display = hit ? '' : 'none';
          if (hit) any = true;
        });
        g.style.display = any ? '' : 'none';
      });
    });
  }

  function fail(msg) {
    el('results-summary').textContent = msg;
  }

  Promise.all([
    fetch(PANTRY_URL).then(function (r) { return r.json(); }),
    fetch(RECIPES_URL).then(function (r) { return r.json(); })
  ]).then(function (res) {
    pantry = res[0];
    recipes = res[1].recipes;
    restore();
    renderPantry();
    wire();
    update();
  }).catch(function (e) {
    fail('Could not load the recipe database. If you are opening this file directly, run it through a web server instead: browsers block fetch() on file:// URLs.');
    if (window.console) console.error(e);
  });
})();
